local TarotCardMaker = {}
local PRODUCTS = {
    simple_wood_tarot = { name = "Preprost leseni tarot", woodCost = 2, parchmentCost = 2, paintCost = 1, time = 5, cost = 80, happiness = 2, mysticism = 18, prestige = 2, description = "Preprost leseni tarot za vedeževanje." },
    painted_parchment_tarot = { name = "Poslikani pergamentni tarot", woodCost = 1, parchmentCost = 3, paintCost = 2, time = 8, cost = 220, happiness = 3, mysticism = 32, prestige = 5, description = "Poslikani pergamentni tarot za trgovce." },
    silver_edged_tarot = { name = "Srebrnorobni tarot", parchmentCost = 3, silverCost = 1, paintCost = 2, time = 11, cost = 540, happiness = 4, mysticism = 48, prestige = 10, description = "Srebrnorobni tarot za plemiče." },
    gold_trimmed_tarot = { name = "Zlatookrasni tarot", parchmentCost = 3, goldCost = 1, silverCost = 1, paintCost = 2, time = 15, cost = 1300, happiness = 5, mysticism = 62, prestige = 18, description = "Zlatookrasni tarot za visoke plemiče." },
    jewel_set_tarot = { name = "Draguljasta tarot", parchmentCost = 3, goldCost = 2, silverCost = 1, paintCost = 2, jewelCost = 1, time = 19, cost = 2900, happiness = 7, mysticism = 78, prestige = 30, description = "Tarot z draguljem za visoko plemstvo." },
    royal_grand_tarot = { name = "Kraljevski veliki tarot", parchmentCost = 5, goldCost = 3, silverCost = 2, paintCost = 3, jewelCost = 2, pearlCost = 2, time = 26, cost = 6500, happiness = 13, mysticism = 95, prestige = 62, description = "Veliki kraljevski tarot z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    tarot_workshop = { name = "Tarotna delavnica", cost = { gold = 240, wood = 100, stone = 100, parchment = 6, paint = 6 }, upkeep = 5, qualityBonus = 5 },
    divination_loft = { name = "Vedeževalna podstrešje", cost = { gold = 880, wood = 240, stone = 220, silver = 6, parchment = 8 }, upkeep = 20, qualityBonus = 18 },
    master_tarot_atelier = { name = "Mojstrski tarotni atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_divination_palace = { name = "Kraljevska vedeževalna palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
TarotCardMaker.parchmentStock = 14; TarotCardMaker.woodStock = 12; TarotCardMaker.paintStock = 14; TarotCardMaker.silverStock = 6; TarotCardMaker.goldStock = 6; TarotCardMaker.jewelStock = 4; TarotCardMaker.pearlStock = 4
TarotCardMaker.productStock = {}; TarotCardMaker.buildings = {}; TarotCardMaker.maker = nil; TarotCardMaker.activeMaking = {}; TarotCardMaker.totalProducts = 0; TarotCardMaker.dayTimer = 0
function TarotCardMaker.init() TarotCardMaker.parchmentStock=14; TarotCardMaker.woodStock=12; TarotCardMaker.paintStock=14; TarotCardMaker.silverStock=6; TarotCardMaker.goldStock=6; TarotCardMaker.jewelStock=4; TarotCardMaker.pearlStock=4; TarotCardMaker.productStock={}; TarotCardMaker.buildings={}; TarotCardMaker.maker=nil; TarotCardMaker.activeMaking={}; TarotCardMaker.totalProducts=0; TarotCardMaker.dayTimer=0; print("[TarotCardMaker] Royal Tarot Card Maker System initialized (6 products, 4 buildings)") end
function TarotCardMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TarotCardMaker.maker={name=n or ("Tarotar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tarotar najet: %s (spretnost: %d)",TarotCardMaker.maker.name,s),"success") end; return true end
function TarotCardMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TarotCardMaker.build(id) local ok,e=TarotCardMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TarotCardMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TarotCardMaker.getQualityBonus() local b=0; for _,bd in ipairs(TarotCardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TarotCardMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.parchmentCost and TarotCardMaker.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.woodCost and TarotCardMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.paintCost and TarotCardMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and TarotCardMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TarotCardMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TarotCardMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TarotCardMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TarotCardMaker.buildings==0 then return false,"Potrebna tarotna delavnica" end; if not TarotCardMaker.maker then return false,"Potreben tarotar" end; return true end
function TarotCardMaker.make(pt,qty) qty=qty or 1; local ok,e=TarotCardMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.parchmentCost then TarotCardMaker.parchmentStock=TarotCardMaker.parchmentStock-d.parchmentCost*qty end; if d.woodCost then TarotCardMaker.woodStock=TarotCardMaker.woodStock-d.woodCost*qty end; if d.paintCost then TarotCardMaker.paintStock=TarotCardMaker.paintStock-d.paintCost*qty end; if d.silverCost then TarotCardMaker.silverStock=TarotCardMaker.silverStock-d.silverCost*qty end; if d.goldCost then TarotCardMaker.goldStock=TarotCardMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TarotCardMaker.jewelStock=TarotCardMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TarotCardMaker.pearlStock=TarotCardMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TarotCardMaker.maker then t=math.max(1,t-math.floor(TarotCardMaker.maker.skill/13)) end; table.insert(TarotCardMaker.activeMaking,{id="tarot_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,mysticism=d.mysticism or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Risba: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TarotCardMaker.completeMaking(m) local q=1.0+(TarotCardMaker.getQualityBonus()/100); if TarotCardMaker.maker then q=q+(TarotCardMaker.maker.skill/140) end; q=math.min(2.5,q); TarotCardMaker.productStock[m.productType]=(TarotCardMaker.productStock[m.productType] or 0)+m.quantity; TarotCardMaker.totalProducts=TarotCardMaker.totalProducts+m.quantity; if m.mysticism>0 and _G.state then _G.state.mysticism=(_G.state.mysticism or 0)+m.mysticism end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TarotCardMaker.maker then TarotCardMaker.maker.itemsMade=TarotCardMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TarotCardMaker.maker.skill=math.min(100,TarotCardMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tarot izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"tarot.completed",{productName=m.productName,mysticism=m.mysticism,prestige=m.prestige,happiness=m.happiness}) end end
function TarotCardMaker.update(dt) if not _G.state then return end; TarotCardMaker.dayTimer=TarotCardMaker.dayTimer+dt; if TarotCardMaker.dayTimer>=30 then TarotCardMaker.dayTimer=0; for i=#TarotCardMaker.activeMaking,1,-1 do local m=TarotCardMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TarotCardMaker.completeMaking(m); table.remove(TarotCardMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TarotCardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TarotCardMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TarotCardMaker.getStats() return {parchmentStock=TarotCardMaker.parchmentStock,woodStock=TarotCardMaker.woodStock,paintStock=TarotCardMaker.paintStock,silverStock=TarotCardMaker.silverStock,goldStock=TarotCardMaker.goldStock,jewelStock=TarotCardMaker.jewelStock,pearlStock=TarotCardMaker.pearlStock,productStock=TarotCardMaker.productStock,numBuildings=#TarotCardMaker.buildings,hasMaker=TarotCardMaker.maker~=nil,makerName=TarotCardMaker.maker and TarotCardMaker.maker.name or "—",makerSkill=TarotCardMaker.maker and TarotCardMaker.maker.skill or 0,activeMaking=#TarotCardMaker.activeMaking,totalProducts=TarotCardMaker.totalProducts} end
return TarotCardMaker
